import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingObstacleListItem,
  mapHikingObstacleOne,
  mapHikingObstacleWithHiking,
} from '../@mappers/hikingObstacles.mapper';
import {
  IHikingObstacleCommonAddResultDTO,
  IHikingObstacleCommonDelByIdDTO,
  IHikingObstacleCreateDTO,
  IHikingObstacleOneDTO,
  IHikingObstacleOneMemberAddDTO,
  IHikingObstacleOnePhotoAddDTO,
  IHikingObstacleOnePhotoUpdateDTO,
  IHikingObstaclesListWithHikingDTO,
  IHikingObstaclesListWithObstacleDTO,
  IHikingObstacleUpdateDTO,
} from '../@types/DTO/hikingObstacles.dto.types';
import {
  IHikingObstacleWithObstacleListItem,
  IHikingObstacleOne,
} from '../@types/hikingObstacles.types';

export const getHikingObstaclesList = async (
  id_hiking: number,
): Promise<IHikingObstacleWithObstacleListItem[]> => {
  const res = await get<IHikingObstaclesListWithObstacleDTO[]>(
    '/ajax/hiking/obstacles/hiking_obstacles_list.php',
    { id_hiking },
  );
  return res.map(mapHikingObstacleListItem);
};

export const addHikingObstacle = async (data: IHikingObstacleCreateDTO): Promise<number> => {
  const res = await post<IHikingObstacleCommonAddResultDTO, IHikingObstacleCreateDTO>(
    '/ajax/hiking/obstacles/hiking_obstacles_add.php',
    data,
  ).then<IHikingObstacleCommonAddResultDTO>(handleApiError);
  return +res.id;
};

export const updateHikingObstacle = async (data: IHikingObstacleUpdateDTO): Promise<boolean> => {
  const res = await post<any, IHikingObstacleUpdateDTO>(
    '/ajax/hiking/obstacles/hiking_obstacles_edit.php',
    data,
  ).then<{ success: string }>(handleApiError);
  return Boolean(res?.success);
};

