export const getHikingOneObstacle = async (
  id_hiking_obstacle: number,
): Promise<IHikingObstacleOne> => {
  const res = await get<IHikingObstacleOneDTO>('/ajax/hiking/obstacles/hiking_obstacles_one.php', {
    id: id_hiking_obstacle,
  });
  return mapHikingObstacleOne(res);
};

