export const getHikingObstaclesByObstacleId = async (id_obstacle: number) => {
  const res = await get<IHikingObstacleOneDTO>(
    '/ajax/hiking/obstacles/hiking_obstacles_list_by_obstacle_id.php',
    {
      id_obstacle,
    },
  ).then<IHikingObstaclesListWithHikingDTO[]>(handleApiError);
  return res.map(mapHikingObstacleWithHiking);
};
